  // ---- Grammar ----
  {"subject": "English", "year": 2542, "question": "Choose the option that correctly completes: 'If she ___ harder, she would have passed.'", "options": ["study", "studied", "had studied", "studies"], "correctIndex": 2, "explanation": "The third conditional uses the past perfect 'had studied' in the if-clause."},
  {"subject": "English", "year": 2543, "question": "Choose the option that correctly completes: 'By next year, he ___ from the university.'", "options": ["will graduate", "will have graduated", "graduates", "graduated"], "correctIndex": 1, "explanation": "Future perfect tense expresses an action that will be completed before a future point in time."},
  {"subject": "English", "year": 2544, "question": "Choose the option that correctly completes: 'The book ___ on the table belongs to me.'", "options": ["lying", "lay", "lied", "laying"], "correctIndex": 0, "explanation": "'Lying' (from 'lie', meaning to rest) correctly describes the book's position."},
  {"subject": "English", "year": 2545, "question": "Choose the option that correctly completes: 'She has been ___ English for five years.'", "options": ["learn", "learning", "learned", "learns"], "correctIndex": 1, "explanation": "Present perfect continuous tense uses 'has been + verb-ing'."},
  {"subject": "English", "year": 2546, "question": "Choose the option that correctly completes: 'Neither the manager nor his assistants ___ available.'", "options": ["was", "is", "were", "be"], "correctIndex": 2, "explanation": "With 'neither...nor', the verb agrees with the nearer subject, 'assistants', which is plural."},
  {"subject": "English", "year": 2547, "question": "Choose the option that correctly completes: 'One of the students ___ absent today.'", "options": ["are", "is", "were", "be"], "correctIndex": 1, "explanation": "'One of' is singular and takes a singular verb."},
  {"subject": "English", "year": 2548, "question": "Choose the option that correctly completes: 'The information ___ very useful.'", "options": ["were", "was", "are", "have been"], "correctIndex": 1, "explanation": "'Information' is an uncountable noun and takes a singular verb."},
  {"subject": "English", "year": 2549, "question": "Choose the option that correctly completes: 'I suggest that he ___ the report immediately.'", "options": ["submits", "submit", "submitted", "submitting"], "correctIndex": 1, "explanation": "The subjunctive mood after 'suggest that' uses the base form of the verb."},
  {"subject": "English", "year": 2550, "question": "Choose the option that correctly completes: 'Hardly had she left ___ the phone rang.'", "options": ["when", "than", "then", "before"], "correctIndex": 0, "explanation": "'Hardly...when' is the correct correlative structure."},
  {"subject": "English", "year": 2551, "question": "Choose the option that correctly completes: 'No sooner had he arrived ___ it started raining.'", "options": ["when", "than", "then", "that"], "correctIndex": 1, "explanation": "'No sooner...than' is the correct correlative structure."},
  {"subject": "English", "year": 2552, "question": "Choose the option that correctly completes: 'She is the woman ___ car was stolen.'", "options": ["who", "whom", "whose", "which"], "correctIndex": 2, "explanation": "'Whose' shows possession, referring to the woman's car."},
  {"subject": "English", "year": 2553, "question": "Choose the option that correctly completes: 'This is the house ___ I was born.'", "options": ["which", "where", "that", "who"], "correctIndex": 1, "explanation": "'Where' introduces a relative clause referring to a place."},
  {"subject": "English", "year": 2554, "question": "Choose the option that correctly completes: 'He behaves as if he ___ the owner of the company.'", "options": ["is", "were", "was", "be"], "correctIndex": 1, "explanation": "'As if' followed by a hypothetical situation uses the subjunctive 'were'."},
  {"subject": "English", "year": 2555, "question": "Choose the option that correctly completes: 'I wish I ___ more time to prepare.'", "options": ["have", "had", "has", "will have"], "correctIndex": 1, "explanation": "'Wish' followed by a past tense expresses a present unfulfilled desire."},
  {"subject": "English", "year": 2556, "question": "Choose the option that correctly completes: 'The two brothers resemble each other ___.'", "options": ["good", "well", "closely", "strong"], "correctIndex": 2, "explanation": "'Closely' is the correct adverb to describe a strong resemblance."},
  {"subject": "English", "year": 2557, "question": "Choose the option that correctly completes: 'Not until she apologised ___ he forgive her.'", "options": ["did", "does", "do", "had"], "correctIndex": 0, "explanation": "'Not until' at the start of a sentence requires inversion with 'did'."},
  {"subject": "English", "year": 2558, "question": "Choose the option that correctly completes: 'Rarely ___ such dedication in a young worker.'", "options": ["we see", "do we see", "we saw", "did we saw"], "correctIndex": 1, "explanation": "'Rarely' at the start of a sentence requires inversion with 'do we see'."},
  {"subject": "English", "year": 2559, "question": "Choose the option that correctly completes: 'She is used to ___ up early.'", "options": ["wake", "waking", "woke", "wakes"], "correctIndex": 1, "explanation": "'Used to' meaning accustomed to is followed by a gerund."},
  {"subject": "English", "year": 2560, "question": "Choose the option that correctly completes: 'They look forward to ___ from you soon.'", "options": ["hear", "hearing", "heard", "hears"], "correctIndex": 1, "explanation": "'Look forward to' is followed by a gerund."},
  {"subject": "English", "year": 2561, "question": "Choose the option that correctly completes: 'He apologised for ___ late.'", "options": ["be", "being", "been", "was"], "correctIndex": 1, "explanation": "'Apologise for' is followed by a gerund."},
  {"subject": "English", "year": 2562, "question": "Choose the option that correctly completes: 'The bridge, ___ was built last year, has already collapsed.'", "options": ["that", "which", "who", "whom"], "correctIndex": 1, "explanation": "'Which' is used in a non-restrictive relative clause referring to a thing."},
  {"subject": "English", "year": 2563, "question": "Choose the option that correctly completes: 'Everyone except John and Mary ___ present.'", "options": ["were", "was", "are", "be"], "correctIndex": 1, "explanation": "'Everyone' is singular and takes a singular verb, 'was'."},
  {"subject": "English", "year": 2564, "question": "Choose the option that correctly completes: 'The jury ___ divided in their opinions.'", "options": ["is", "are", "was", "has"], "correctIndex": 1, "explanation": "When members of a collective noun act individually, a plural verb, 'are', is used."},
  {"subject": "English", "year": 2565, "question": "Choose the option that correctly completes: 'A number of students ___ absent from class.'", "options": ["is", "was", "are", "has been"], "correctIndex": 2, "explanation": "'A number of' takes a plural verb, unlike 'the number of' which takes a singular verb."},
  {"subject": "English", "year": 2566, "question": "Choose the option that correctly completes: 'The number of applicants ___ increasing every year.'", "options": ["is", "are", "were", "have"], "correctIndex": 0, "explanation": "'The number of' takes a singular verb."},
  {"subject": "English", "year": 2567, "question": "Choose the option that correctly completes: 'Either the manager or the supervisors ___ responsible for the error.'", "options": ["is", "are", "was", "has been"], "correctIndex": 1, "explanation": "With 'either...or', the verb agrees with the nearer subject, 'supervisors', which is plural."},
  {"subject": "English", "year": 2568, "question": "Choose the option that correctly completes: 'She would rather stay home than ___ to the noisy party.'", "options": ["go", "going", "went", "goes"], "correctIndex": 0, "explanation": "'Would rather...than' is followed by the base form of the verb."},
  {"subject": "English", "year": 2569, "question": "Choose the option that correctly completes: 'It is time the government ___ action on the matter.'", "options": ["take", "takes", "took", "taking"], "correctIndex": 2, "explanation": "'It is time' followed by a subject uses the past tense to express an urgent present need."},
  {"subject": "English", "year": 2570, "question": "Choose the option that correctly completes: 'The teacher, along with her students, ___ attending the seminar.'", "options": ["are", "is", "were", "have been"], "correctIndex": 1, "explanation": "Phrases like 'along with' do not affect subject-verb agreement; the verb agrees with the singular subject 'teacher'."},
  {"subject": "English", "year": 2571, "question": "Choose the option that correctly completes: 'Scarcely had the plane landed ___ the passengers began to disembark.'", "options": ["when", "than", "then", "that"], "correctIndex": 0, "explanation": "'Scarcely...when' is the correct correlative structure."},

  // ---- Figures of Speech ----
  {"subject": "English", "year": 2572, "question": "Identify the figure of speech: 'O Death, where is thy sting?'", "options": ["Simile", "Apostrophe", "Metaphor", "Onomatopoeia"], "correctIndex": 1, "explanation": "Apostrophe is a figure of speech in which an absent or non-human entity is addressed directly."},
  {"subject": "English", "year": 2573, "question": "Identify the figure of speech: 'He is not the smartest student in class' (implying he is quite dull).", "options": ["Hyperbole", "Litotes", "Metaphor", "Irony"], "correctIndex": 1, "explanation": "Litotes is an understatement created by negating the opposite, softening a harsh statement."},
  {"subject": "English", "year": 2574, "question": "Identify the figure of speech: 'The bark of the tree fell as the dog began to bark.'", "options": ["Pun", "Simile", "Metaphor", "Irony"], "correctIndex": 0, "explanation": "A pun plays on the multiple meanings of a word, here 'bark' meaning tree covering and a dog's sound."},
  {"subject": "English", "year": 2575, "question": "Identify the figure of speech: 'I must be cruel only to be kind.'", "options": ["Oxymoron", "Paradox", "Simile", "Metonymy"], "correctIndex": 1, "explanation": "A paradox is a statement that seems contradictory but reveals an underlying truth."},
  {"subject": "English", "year": 2576, "question": "Identify the figure of speech: 'We shall fight on the beaches, we shall fight on the landing grounds, we shall fight in the fields.'", "options": ["Anaphora", "Antithesis", "Euphemism", "Chiasmus"], "correctIndex": 0, "explanation": "Anaphora is the repetition of a phrase at the beginning of successive clauses for emphasis."},
  {"subject": "English", "year": 2577, "question": "Identify the figure of speech: 'The rain in Spain falls mainly on the plain.'", "options": ["Assonance", "Alliteration", "Consonance", "Rhyme"], "correctIndex": 0, "explanation": "Assonance is the repetition of vowel sounds, here the repeated 'ai' sound."},
  {"subject": "English", "year": 2578, "question": "Identify the figure of speech: 'Mike likes his new bike.'", "options": ["Consonance", "Alliteration", "Assonance", "Rhyme"], "correctIndex": 0, "explanation": "Consonance is the repetition of consonant sounds within words, here the repeated 'k' sound."},
  {"subject": "English", "year": 2579, "question": "Identify the figure of speech: 'Is the Pope Catholic?' (used to imply an obviously affirmative answer).", "options": ["Rhetorical question", "Paradox", "Litotes", "Hyperbole"], "correctIndex": 0, "explanation": "A rhetorical question is asked to make a point rather than to get an actual answer."},
  {"subject": "English", "year": 2580, "question": "Identify the figure of speech: 'He met his Waterloo in the final match.'", "options": ["Allusion", "Metaphor", "Simile", "Metonymy"], "correctIndex": 0, "explanation": "Allusion is an indirect reference to a well-known event, here Napoleon's defeat at Waterloo."},
  {"subject": "English", "year": 2581, "question": "Identify the figure of speech: 'The dove flew over the peace conference.'", "options": ["Symbolism", "Metaphor", "Simile", "Personification"], "correctIndex": 0, "explanation": "Symbolism uses an object, here a dove, to represent an idea, in this case peace."},
  {"subject": "English", "year": 2582, "question": "Identify the figure of speech: 'The soldier fought bravely, fought fiercely, fought until his last breath.'", "options": ["Repetition", "Antithesis", "Euphemism", "Chiasmus"], "correctIndex": 0, "explanation": "Repetition emphasises an idea by repeating a word or phrase, here 'fought'."},
  {"subject": "English", "year": 2583, "question": "Identify the figure of speech: 'It was a tiny little pebble.'", "options": ["Tautology", "Hyperbole", "Litotes", "Oxymoron"], "correctIndex": 0, "explanation": "Tautology is the needless repetition of an idea using different words, here 'tiny' and 'little'."},
  {"subject": "English", "year": 2584, "question": "Identify the figure of speech: 'He climbed the ladder of success step by step, rung by rung, until he reached the very top.'", "options": ["Climax", "Anticlimax", "Antithesis", "Chiasmus"], "correctIndex": 0, "explanation": "Climax arranges ideas in order of increasing importance or intensity."},
  {"subject": "English", "year": 2585, "question": "Identify the figure of speech: 'The senator promised to fight for justice, freedom, and a free parking space.'", "options": ["Anticlimax", "Climax", "Hyperbole", "Euphemism"], "correctIndex": 0, "explanation": "Anticlimax is a sudden drop from something serious or important to something trivial, often for humorous effect."},
  {"subject": "English", "year": 2586, "question": "Identify the figure of speech: 'She opened the door and her heart to the stranger.'", "options": ["Zeugma", "Metaphor", "Simile", "Personification"], "correctIndex": 0, "explanation": "Zeugma uses a single word, here 'opened', to govern two other words in different senses."},

